CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (tenant_id uuid REFERENCES organizations(id), user_id text REFERENCES users(id), role text NOT NULL CHECK (role IN ('owner','admin','editor','viewer')), PRIMARY KEY (tenant_id,user_id));
CREATE TABLE apps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, app_id uuid NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', workflow_enabled boolean NOT NULL DEFAULT false, reviewer_role text NOT NULL DEFAULT 'admin' CHECK(reviewer_role IN ('admin','editor')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,app_id) REFERENCES apps(tenant_id,id));
CREATE TABLE fields (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, collection_id uuid NOT NULL, key text NOT NULL CHECK(key ~ '^[a-z][a-z0-9_]{0,49}$'), label text NOT NULL, type text NOT NULL CHECK(type IN ('text','textarea','number','date','boolean','select')), required boolean NOT NULL DEFAULT false, options jsonb NOT NULL DEFAULT '[]', position integer NOT NULL DEFAULT 0, UNIQUE(tenant_id,id), UNIQUE(tenant_id,collection_id,id), UNIQUE(collection_id,key), FOREIGN KEY(tenant_id,collection_id) REFERENCES collections(tenant_id,id));
CREATE TABLE field_permissions (tenant_id uuid NOT NULL, field_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','admin','editor','viewer')), can_write boolean NOT NULL DEFAULT false, PRIMARY KEY(field_id,role), FOREIGN KEY(tenant_id,field_id) REFERENCES fields(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, collection_id uuid NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','rejected')), created_by text NOT NULL REFERENCES users(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,collection_id,id), FOREIGN KEY(tenant_id,collection_id) REFERENCES collections(tenant_id,id));
CREATE TABLE record_values (tenant_id uuid NOT NULL, collection_id uuid NOT NULL, record_id uuid NOT NULL, field_id uuid NOT NULL, value jsonb NOT NULL, PRIMARY KEY(record_id,field_id), FOREIGN KEY(tenant_id,collection_id,record_id) REFERENCES records(tenant_id,collection_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,collection_id,field_id) REFERENCES fields(tenant_id,collection_id,id));
CREATE TABLE approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, record_id uuid NOT NULL, requested_by text NOT NULL REFERENCES users(id), reviewer_role text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), decided_by text REFERENCES users(id), comment text, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, FOREIGN KEY(tenant_id,record_id) REFERENCES records(tenant_id,id));
CREATE UNIQUE INDEX one_pending_approval ON approvals(record_id) WHERE status='pending';
CREATE TABLE files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, record_id uuid NOT NULL, name text NOT NULL, object_key text NOT NULL UNIQUE, mime text NOT NULL, size bigint NOT NULL, uploaded_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,record_id) REFERENCES records(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), actor text NOT NULL, action text NOT NULL, entity_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES organizations(id), kind text NOT NULL, record_id uuid, actor text NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,record_id) REFERENCES records(tenant_id,id));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES organizations(id), user_id text NOT NULL REFERENCES users(id), event_id uuid NOT NULL REFERENCES outbox(id), message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id));
CREATE INDEX records_tenant_collection ON records(tenant_id,collection_id,created_at DESC);
CREATE INDEX values_tenant ON record_values(tenant_id,record_id);
CREATE INDEX approvals_tenant ON approvals(tenant_id,status);
CREATE INDEX notifications_user ON notifications(tenant_id,user_id,created_at DESC);
CREATE INDEX audit_tenant ON audit_logs(tenant_id,created_at DESC);
CREATE INDEX outbox_ready ON outbox(available_at) WHERE delivered_at IS NULL;
GRANT USAGE ON SCHEMA public TO hasura;
GRANT SELECT ON organizations,memberships,apps,collections,fields,field_permissions,records,record_values,approvals,files,notifications TO hasura;
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,record_id uuid NOT NULL,author text NOT NULL REFERENCES users(id),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,record_id) REFERENCES records(tenant_id,id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON comments TO hasura;
